fn handle_blobs_by_range_request_inner(&self, ..., req: BlobsByRangeRequest)
    -> Result<(), (RpcErrorResponse, &'static str)> {
    let data_availability_boundary_slot = match self.chain.data_availability_boundary() {
        Some(boundary) => boundary.start_slot(T::EthSpec::slots_per_epoch()),
        None => return Err((RpcErrorResponse::InvalidRequest, "Deneb fork is disabled")),
    };
    let oldest_blob_slot = self.chain.store.get_blob_info().oldest_blob_slot
        .unwrap_or(data_availability_boundary_slot);
    if request_start_slot < oldest_blob_slot {
        return if data_availability_boundary_slot < oldest_blob_slot {
            Err((RpcErrorResponse::ResourceUnavailable, "blobs pruned within boundary"))
        } else {
            Err((RpcErrorResponse::InvalidRequest, "Req outside availability period"))
        };
    }
    // Note: handler currently validates against data_availability_boundary not FULU_FORK_EPOCH
}

