pub fn enr_fork_id<E: EthSpec>(&self, slot: Slot, genesis_validators_root: Hash256) -> EnrForkId {
    EnrForkId {
        fork_digest: self.compute_fork_digest(genesis_validators_root, slot.epoch(E::slots_per_epoch())),
        next_fork_version: self.next_fork_version::<E>(slot),
        next_fork_epoch: self.next_digest_epoch(slot.epoch(E::slots_per_epoch()))
            .unwrap_or(self.far_future_epoch),
    }
}

